    `<div class="grid main-side">${panel('Dự báo so với thực tế','Bốn tuần test không chồng nhau · USD',`<div class="table-toolbar"><select id="forecastModelSelect" class="inline-select" aria-label="Chọn mô hình">${D.forecast_test_metrics.map(v=>`<option value="${v.model}" ${v.model===forecastModel?'selected':''}>${modelNames[v.model]}</option>`).join('')}</select><select id="forecastSeriesSelect" class="inline-select" aria-label="Chọn nhóm dự báo"><option value="ALL">Tổng tất cả nhóm</option>${series.map(v=>`<option ${v===forecastSeries?'selected':''}>${escapeHtml(v)}</option>`).join('')}</select></div>`+chartDiv('forecastHistory','big-chart'))}${panel('Quyết định lựa chọn model','Chọn bằng validation trước khi mở test',`<div class="hero-dark"><div class="eyebrow">CHAMPION</div><h2>Trung bình 28 ngày</h2><p>WAPE validation 5,39% · test 14,99%. Các mô hình ML đã train nhưng chưa vượt baseline trong thiết kế này.</p></div><ul class="info-list"><li><h3>Không chọn lại theo test</h3><p>Test dùng để đánh giá phương án đã chọn. Cải tiến taxonomy hoặc feature cần một vòng đánh giá mới.</p></li><li><h3>Đây là tiền bán theo nhóm</h3><p>Chưa phải nhu cầu SKU–cửa hàng hoặc số lượng đặt hàng.</p></li></ul>`)}</div>`+
    `<div class="grid two">${panel('So sánh validation và test','WAPE của toàn bộ nhóm · thấp hơn tốt hơn',chartDiv('forecastModelCompare'))}${panel('Nhóm đóng góp sai số','Champion mean_28_days · tỷ trọng sai số tuyệt đối',chartDiv('forecastErrorShare'))}</div>`+
    note('<b>Dải dự báo chưa đủ độ bao phủ.</b> Dải residual heuristic bao phủ 61,9% cặp nhóm–origin test. Khi loại tuần chứa ngày 25/12 vắng bản ghi, WAPE baseline là 12,35%. Không dùng dải này để cam kết mức dịch vụ tồn kho.','warning')+
    `<div class="grid two">${panel('Sai số theo nhóm','Bốn tuần test của champion',table('forecastSeriesMetrics',['Nhóm','WAPE','Bias','MAE USD'],D.forecast_series_metrics.slice().sort((a,b)=>b.WAPE-a.WAPE),['series',v=>P(v.WAPE),v=>P(v.bias),v=>N(v.MAE,2)],{numeric:[1,2,3]}),csvButton('forecastSeriesMetrics'))}${panel('Dự báo 7 ngày tiếp theo','Model đã refit trên các nhãn hoàn thành đến 31/12/2017',table('futureForecast',['Nhóm','Dự báo USD','Dải dưới','Dải trên'],D.forecast_next_7_days.slice().sort((a,b)=>b.forecast-a.forecast),['series',v=>N(v.forecast,2),v=>N(v.lower_heuristic,2),v=>N(v.upper_heuristic,2)],{numeric:[1,2,3]}),csvButton('futureForecast'))}</div>`+
    panel('Kết quả theo phương án','Giữ nguyên mọi ứng viên để đối chiếu',table('forecastLeaderboard',['Phương án','Validation WAPE','Test WAPE','Test bias','Vai trò'],D.forecast_validation_leaderboard.map(v=>({...v,test:D.forecast_test_metrics.find(x=>x.model===v.model)})),[v=>modelNames[v.model],v=>P(v.WAPE,2),v=>P(v.test?.WAPE,2),v=>P(v.test?.bias,2),v=>v.model==='mean_28_days'?'<span class="status">Champion</span>':'<span class="status gray">Ứng viên so sánh</span>'],{numeric:[1,2,3]}),csvButton('forecastLeaderboard'));
  const origins=[...new Set(preds.map(v=>v.origin))].sort(),actuals=origins.map(o=>sum(preds.filter(v=>v.origin===o),'actual')),predicted=origins.map(o=>sum(preds.filter(v=>v.origin===o),'prediction'));
  plot('forecastHistory',[{type:'scatter',mode:'lines+markers',x:origins,y:actuals,name:'Thực tế',line:{color:C.green,width:2.5},marker:{size:7},hovertemplate:'%{x}<br>Thực tế %{y:,.2f} USD<extra></extra>'},{type:'scatter',mode:'lines+markers',x:origins,y:predicted,name:modelNames[forecastModel],line:{color:C.amber,width:2,dash:'dash'},marker:{symbol:'square',size:6},hovertemplate:'%{x}<br>Dự báo %{y:,.2f} USD<extra></extra>'}],{showlegend:true,legend:{orientation:'h',x:0,y:1.13,font:{size:10}},margin:{l:65,r:15,t:35,b:45},xaxis:{title:'Origin · dự báo 7 ngày sau mốc này',type:'category'},yaxis:{tickformat:',.0f'}},350);
  const lb=D.forecast_validation_leaderboard;plot('forecastModelCompare',[{type:'bar',x:lb.map(v=>modelNames[v.model]),y:lb.map(v=>v.WAPE),name:'Validation',marker:{color:'#a6c19b'}},{type:'bar',x:lb.map(v=>modelNames[v.model]),y:lb.map(v=>D.forecast_test_metrics.find(x=>x.model===v.model)?.WAPE),name:'Test',marker:{color:C.green}}],{barmode:'group',showlegend:true,legend:{orientation:'h',y:1.13},yaxis:{tickformat:'.0%'},xaxis:{tickangle:-20},margin:{l:45,r:10,t:30,b:80}},330);
  horizontal('forecastErrorShare',D.forecast_error_contribution.map(v=>({name:v.series,...v})),'error_share',8,true);
  $('forecastModelSelect').onchange=e=>{forecastModel=e.target.value;render();};$('forecastSeriesSelect').onchange=e=>{forecastSeries=e.target.value;render();};
