function safeStorageGet(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}}
function safeStorageSet(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{return false;}}
function riskActionsHtml(){const rows=D.customer_risk_actions,n=Math.ceil(rows.length*.2);return `<div class="kpi-grid">${kpi('Hộ được score',N(rows.length),'hộ','Có mua dương trong 90 ngày trước 31/12',null,'users')}${kpi('Nhóm ưu tiên top 20%',N(n),'hộ','Ngưỡng công suất giả định',null,'spark')}${kpi('Mốc dữ liệu','31/12','2017','Nhãn 28 ngày tiếp theo chưa có đầy đủ',null,'flow')}${kpi('Đã đánh dấu xem',N(Object.keys(safeStorageGet('retailReviewed',{})).length),'hộ','Trạng thái local trong trình duyệt này',null,'shield')}</div>`+note('Danh sách là <b>điểm dự báo</b>, chưa có nhãn tương lai. Nút “Đã xem” chỉ lưu trên trình duyệt; không gửi thông tin tới CRM và không liên hệ khách.','warning')+panel('Danh sách rà soát cuối kỳ','Xếp theo model khách hàng đã refit; không điều chỉnh score khi lọc danh sách',`<div class="table-toolbar"><input id="riskCustomerSearch" class="search-field" placeholder="Tìm mã hộ…" aria-label="Tìm hộ trong danh sách score"><select id="riskQueueFilter" class="inline-select"><option value="priority">Top 20% ưu tiên</option><option value="all">Tất cả hộ được score</option><option value="reviewed">Đã đánh dấu xem</option></select><span class="subtext" id="riskQueueCount"></span></div><div id="riskQueueArea"></div>`,csvButton('riskQueue'));}
function setupRiskActions(){const draw=()=>{const reviewed=safeStorageGet('retailReviewed',{}),query=$('riskCustomerSearch').value.trim(),mode=$('riskQueueFilter').value;const sorted=D.customer_risk_actions.slice().sort((a,b)=>b.risk_score-a.risk_score),priority=Math.ceil(sorted.length*.2);const rows=sorted.filter((v,i)=>(mode==='all'||(mode==='priority'?i<priority:reviewed[String(v.household_id)]))&&(!query||String(v.household_id).includes(query)));$('riskQueueCount').textContent=N(rows.length)+' hộ · hiển thị tối đa 250';$('riskQueueArea').innerHTML=table('riskQueue',['Mã hộ','Điểm rủi ro','Recency','Giỏ 90 ngày','Sales 90 ngày USD','Rà soát'],rows.slice(0,250),[v=>`<button class="link-button" data-customer="${v.household_id}">Hộ ${v.household_id}</button>`,v=>N(v.risk_score,3),v=>N(v.recency),v=>N(v.visits_90),v=>N(v.sales_90,2),v=>`<button class="button small" data-review-customer="${v.household_id}">${reviewed[String(v.household_id)]?'✓ Đã xem':'Đánh dấu xem'}</button>`],{numeric:[1,2,3,4]});exports.set('riskQueue',{headers:['Mã hộ','Điểm rủi ro','Recency','Giỏ 90 ngày','Sales 90 ngày USD'],rows,fields:['household_id','risk_score','recency','visits_90','sales_90']});};draw();$('riskCustomerSearch').oninput=draw;$('riskQueueFilter').onchange=draw;window.refreshRiskQueue=draw;}
