  $('inventorySku').onchange=e=>{inventoryIndex=+e.target.value;render();};document.querySelectorAll('[data-inventory]').forEach(el=>el.oninput=calculateInventory);$('demandMultiplier').oninput=calculateInventory;$('saveInventory').onclick=()=>{const fields={};document.querySelectorAll('[data-inventory]').forEach(el=>fields[el.dataset.inventory]=Math.max(0,+el.value||0));fields.demandMultiplier=+$('demandMultiplier').value;saved[item.sku]=fields;toast(safeStorageSet('retailInventory',saved)?'Đã lưu kịch bản trên trình duyệt.':'Trình duyệt không cho lưu local.');};calculateInventory();
