function calculateInventory(){const item=D.inventorySandbox[inventoryIndex],get=k=>Math.max(0,+$('inv-'+k).value||0),stock=get('stockAssumed'),inbound=get('inboundAssumed'),lead=get('leadAssumed'),review=get('reviewDays'),buffer=get('bufferDays'),pack=Math.max(1,get('casePackAssumed')),moq=Math.max(1,get('MOQAssumed')),factor=+$('demandMultiplier').value/100,daily=item.dailyObservedUnits*factor,target=daily*(lead+review+buffer),short=Math.max(0,target-stock-inbound),order=short>0?Math.ceil(Math.max(short,moq)/pack)*pack:0;const coverage=daily>0?stock/daily:null;$('demandMultiplierValue').textContent=P(factor,0);$('inventoryResult').innerHTML=`<div class="scenario-result"><span>ĐỀ XUẤT BỔ SUNG GIẢ ĐỊNH</span><strong>${N(order)}<small> đơn vị cùng SKU</small></strong></div><div class="notice-row"><span>Nhu cầu ngày tham chiếu</span><b>${N(daily,2)}</b></div><div class="notice-row"><span>Tồn mục tiêu</span><b>${N(target,1)}</b></div><div class="notice-row"><span>Ngày tồn hiện tại</span><b>${N(coverage,1)} ngày</b></div><div class="notice-row"><span>Thiếu trước làm tròn</span><b>${N(short,1)}</b></div>${badge(coverage!=null&&coverage<lead?'Nguy cơ cạn trước ngày nhận':'Cần kiểm tra sức chứa & hạn dùng',coverage!=null&&coverage<lead?'amber':'')}`;
  const days=Array.from({length:Math.min(90,Math.ceil(lead+review+buffer)+8)},(_,i)=>i),base=days.map(d=>stock-daily*d+(d>=lead?inbound:0)),withOrder=days.map(d=>stock-daily*d+(d>=lead?inbound+order:0));plot('inventoryTimeline',[{type:'scatter',mode:'lines',x:days,y:base,name:'Không thêm đơn đề xuất',line:{color:C.amber,dash:'dash'}},{type:'scatter',mode:'lines',x:days,y:withOrder,name:'Nhận đề xuất ở ngày lead',line:{color:C.green,width:2.5}}],{showlegend:true,legend:{orientation:'h',y:1.14,font:{size:9}},xaxis:{title:'Ngày kể từ mốc kịch bản'},yaxis:{title:'Tồn khả dụng mô phỏng'},shapes:[{type:'line',xref:'paper',x0:0,x1:1,y0:0,y1:0,line:{color:C.red,width:1}}],margin:{l:50,r:10,t:35,b:40}},330);
}
